#include "pinyin_phrase_dict.h"

#include <stdbool.h>
#include <string.h>

/* Generated by tools/generate_pinyin_phrase_dict.py from 现代汉语词典（第7版）-拼音.txt + HSK/common phrases + pinyin_location_phrases.txt (<= 4 CJK chars). */

#include "pinyin_phrase_word_pool.inc"
#include "pinyin_phrase_abbr_pool.inc"
#include "pinyin_phrase_index.inc"
#include "pinyin_phrase_priority.inc"

static const char *pinyin_phrase_get_abbr_by_index(size_t index)
{
    if (index >= (sizeof(s_phrase_abbr_offsets) / sizeof(s_phrase_abbr_offsets[0]))) {
        return "";
    }
    return &s_phrase_abbr_pool[s_phrase_abbr_offsets[index]];
}

static bool pinyin_phrase_starts_with(const char *text, const char *prefix)
{
    if (!text || !prefix) {
        return false;
    }
    while (*prefix) {
        if (*text++ != *prefix++) {
            return false;
        }
    }
    return true;
}

static size_t pinyin_phrase_lower_bound(const char *py)
{
    size_t lo = 0;
    size_t hi = sizeof(s_phrase_entries) / sizeof(s_phrase_entries[0]);

    while (lo < hi) {
        size_t mid = lo + ((hi - lo) / 2);
        int cmp = strcmp(py, s_phrase_entries[mid].py);
        if (cmp <= 0) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }

    return lo;
}

const pinyin_phrase_entry_t *pinyin_phrase_lookup(const char *py)
{
    size_t index;

    if (!py || !py[0]) {
        return NULL;
    }

    index = pinyin_phrase_lower_bound(py);
    if (index < (sizeof(s_phrase_entries) / sizeof(s_phrase_entries[0])) &&
        strcmp(py, s_phrase_entries[index].py) == 0) {
        return &s_phrase_entries[index];
    }

    return NULL;
}

static bool pinyin_phrase_word_already_added(const char **out_words, uint16_t count, const char *word)
{
    for (uint16_t i = 0; i < count; i++) {
        if (strcmp(out_words[i], word) == 0) {
            return true;
        }
    }
    return false;
}

static uint16_t pinyin_phrase_add_priority_words(const char *query,
                                                 const char **out_words,
                                                 uint16_t count,
                                                 uint16_t max_words)
{
    bool use_abbr = strlen(query) >= 2;

    for (size_t i = 0; i < (sizeof(s_phrase_priorities) / sizeof(s_phrase_priorities[0])) && count < max_words; i++) {
        const pinyin_phrase_priority_t *priority = &s_phrase_priorities[i];
        if (strcmp(priority->py, query) == 0 ||
            pinyin_phrase_starts_with(priority->py, query) ||
            (use_abbr && pinyin_phrase_starts_with(priority->abbr, query))) {
            if (!pinyin_phrase_word_already_added(out_words, count, priority->word)) {
                out_words[count++] = priority->word;
            }
        }
    }

    return count;
}

static uint16_t pinyin_phrase_add_entry_words(const pinyin_phrase_entry_t *entry,
                                              const char **out_words,
                                              uint16_t count,
                                              uint16_t max_words)
{
    for (uint16_t i = 0; entry && i < entry->word_count && count < max_words; i++) {
        const char *word = pinyin_phrase_get_word(entry, i);
        if (word && !pinyin_phrase_word_already_added(out_words, count, word)) {
            out_words[count++] = word;
        }
    }
    return count;
}

uint16_t pinyin_phrase_collect(const char *query, const char **out_words, uint16_t max_words)
{
    const size_t entry_count = sizeof(s_phrase_entries) / sizeof(s_phrase_entries[0]);
    uint16_t count = 0;
    size_t start;

    if (!query || !query[0] || !out_words || max_words == 0) {
        return 0;
    }

    count = pinyin_phrase_add_priority_words(query, out_words, count, max_words);
    if (count >= max_words) {
        return count;
    }

    const pinyin_phrase_entry_t *exact = pinyin_phrase_lookup(query);
    count = pinyin_phrase_add_entry_words(exact, out_words, count, max_words);
    if (count >= max_words) {
        return count;
    }

    start = pinyin_phrase_lower_bound(query);
    for (size_t i = start; i < entry_count && count < max_words; i++) {
        if (!pinyin_phrase_starts_with(s_phrase_entries[i].py, query)) {
            break;
        }
        count = pinyin_phrase_add_entry_words(&s_phrase_entries[i], out_words, count, max_words);
    }

    if (strlen(query) >= 2) {
        for (size_t i = 0; i < entry_count && count < max_words; i++) {
            const char *abbr = pinyin_phrase_get_abbr_by_index(i);
            if (pinyin_phrase_starts_with(abbr, query)) {
                count = pinyin_phrase_add_entry_words(&s_phrase_entries[i], out_words, count, max_words);
            }
        }
    }

    return count;
}

const char *pinyin_phrase_get_word(const pinyin_phrase_entry_t *entry, uint16_t index)
{
    uint32_t word_index;

    if (!entry || index >= entry->word_count) {
        return NULL;
    }

    word_index = entry->first_word + index;
    if (word_index >= (sizeof(s_phrase_word_offsets) / sizeof(s_phrase_word_offsets[0]))) {
        return NULL;
    }

    return &s_phrase_word_pool[s_phrase_word_offsets[word_index]];
}

size_t pinyin_phrase_entry_count(void)
{
    return sizeof(s_phrase_entries) / sizeof(s_phrase_entries[0]);
}

size_t pinyin_phrase_word_count(void)
{
    return sizeof(s_phrase_word_offsets) / sizeof(s_phrase_word_offsets[0]);
}
